'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Wełna mineralna w szkielecie i izolacja fasadowa 150 mm.","ventilation":"rekuperacja","wallBuildUp":"Szkielet LGS + wełna mineralna, płyta cementowo-wiórowa, wiatroizolacja, izolacja fasadowa 150 mm, paroizolacja, płyta G-K (x2).","heatSourceOther":"Brak danych na stronie producenta.","constructionTechnology":"modulowa-stal-lekka","heatTransferCoefficients":"nieznana"}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, 23.49, '[]'::jsonb, '[{"id":"fdpl-z556-faq-1","answer":"Tak, cena szacunkowa pakietu All-Inclusive to 2 218 136 zł. Obejmuje wszystko z pakietu Pod klucz oraz płytę fundamentową, rekuperację z odzyskiem ciepła, kuchnię na wymiar z kompletnym AGD i pełne wyposażenie łazienek (armatura, ceramika, płytki). Pełne umeblowanie jest opcją wycenianą indywidualnie.","question":"Czy dostępny jest pakiet All-Inclusive i ile kosztuje?"},{"id":"fdpl-z556-faq-2","answer":"Inwestycja jest podzielona na osiem etapów, a kolejną transzę wpłaca się po sprawdzeniu efektów poprzedniej: 10% projekt i rezerwacja, 20% uruchomienie maszyn, 10% odbiór w fabryce, 10% pakowanie i wysyłka, 10% materiał na działce, 10% złożenie bryły, 15% stan deweloperski, 15% przekazanie kluczy. Po podpisaniu umowy cena materiałów zostaje zamrożona na cały okres budowy.","question":"Jak wygląda harmonogram płatności i czy cena jest stała?"},{"id":"fdpl-z556-faq-3","answer":"Od zamówienia do odbioru kluczy realizacja trwa 4-6 miesięcy, a montaż na działce do 14 dni. Producent zapewnia transport i montaż; fundament płytowy jest dodatkowym kosztem poza pakietem All-Inclusive, a wymiana gruntu jest rozliczana według faktycznych kosztów.","question":"Ile trwa realizacja od zamówienia do odbioru kluczy?"}]'::jsonb, NULL, NULL, NULL, 'framedev-7', NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('4651dcb2-4aa1-403f-8e50-134d59c2621d', '5e6c169c-3a7f-57a8-a90d-22b12e38fe84', 'en', 'FrameDEV 4', 'A single-storey house with a flat roof and a covered terrace, with 166 m² of usable area and a garage. Four bedrooms, two bathrooms, walk-in wardrobes and an open living area. Underfloor heating throughout the house, ventilation with heat recovery.', '2026-10-21T17:43:48.460Z'::timestamptz, '2026-10-21T18:12:15.941Z'::timestamptz, '[{"id":"hk106-room-0","name":"Entrance lobby"},{"id":"hk106-room-1","name":"Walk-in wardrobe"},{"id":"hk106-room-2","name":"Hallway"},{"id":"hk106-room-3","name":"Living area"},{"id":"hk106-room-4","name":"Pantry"},{"id":"hk106-room-5","name":"Bedroom"},{"id":"hk106-room-6","name":"Bedroom"},{"id":"hk106-room-7","name":"Bedroom"},{"id":"hk106-room-8","name":"Walk-in wardrobe"},{"id":"hk106-room-9","name":"Bathroom"},{"id":"hk106-room-10","name":"Walk-in wardrobe"},{"id":"hk106-room-11","name":"Study"},{"id":"hk106-room-12","name":"Laundry room"},{"id":"hk106-room-13","name":"Bathroom"},{"id":"hk106-room-14","name":"Utility room"},{"id":"hk106-room-15","name":"Garage"}]'::jsonb, '[{"id":"hk106-faq-1","answer":"Yes, the estimated price of the All-Inclusive package is PLN 1,377,390. It covers everything in the Turnkey package plus the foundation slab, heat recovery ventilation, a made-to-measure kitchen with full appliances and complete bathroom fittings (taps, sanitaryware, tiles). Full furnishing is an option priced individually.","question":"Is the All-Inclusive package available and how much does it cost?"},{"id":"hk106-faq-2","answer":"The investment is split into eight stages and the next instalment is paid after the previous result has been checked: 10% design and reservation, 20% machine start-up, 10% factory acceptance, 10% packing and shipping, 10% materials on site, 10% shell assembly, 15% shell-and-core stage, 15% handover of keys. After the contract is signed the price of materials is frozen for the whole construction period.","question":"What is the payment schedule and is the price fixed?"},{"id":"hk106-faq-3","answer":"From order to handover of the keys the build takes 4-6 months, with on-site assembly of up to 14 days. The producer provides transport and assembly; the foundation slab is an extra cost outside the All-Inclusive package, and soil replacement is charged at actual cost.","question":"How long does the build take from order to handover of the keys?"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Prefabricated LGS steel frame (galvanised profiles) with mineral wool filling, cement-bonded particleboard, wind barrier and 150 mm facade insulation.', 'Flat roof with an EPDM membrane', 'The design can be adapted with the producer''s architects: changing the partition layout, the size and placement of windows and modifying the building form.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('630a1a4d-6e50-4c67-88ce-11009d5b75f5', 'd45da285-893f-5a27-aa33-81c92a9153f2', 'en', 'FrameDEV 5', 'A two-storey house with a compact white form and a pergola by the terrace, with 192 m² of usable area and a garage. Four bedrooms and three bathrooms. Air-source heat pump, underfloor heating throughout the house, ventilation with heat recovery.', '2026-10-21T17:43:48.657Z'::timestamptz, '2026-10-21T18:12:16.828Z'::timestamptz, '[{"id":"hk111-room-0","name":"Entrance lobby"},{"id":"hk111-room-1","name":"Walk-in wardrobe"},{"id":"hk111-room-2","name":"Hallway"},{"id":"hk111-room-3","name":"Living area"},{"id":"hk111-room-4","name":"Pantry"},{"id":"hk111-room-5","name":"Bathroom"},{"id":"hk111-room-6","name":"Study"},{"id":"hk111-room-7","name":"Utility room"},{"id":"hk111-room-8","name":"Hallway with stairs"},{"id":"hk111-room-9","name":"Gym"},{"id":"hk111-room-10","name":"Storage closet"},{"id":"hk111-room-11","name":"Walk-in wardrobe"},{"id":"hk111-room-12","name":"Bedroom"},{"id":"hk111-room-13","name":"Walk-in wardrobe"},{"id":"hk111-room-14","name":"Bathroom"},{"id":"hk111-room-15","name":"Bathroom"},{"id":"hk111-room-16","name":"Bedroom"},{"id":"hk111-room-17","name":"Bedroom"},{"id":"hk111-room-18","name":"Laundry room"}]'::jsonb, '[{"id":"hk111-faq-1","answer":"Yes, the estimated price of the All-Inclusive package is PLN 1,583,771. It covers everything in the Turnkey package plus the foundation slab, heat recovery ventilation, a made-to-measure kitchen with full appliances and complete bathroom fittings (taps, sanitaryware, tiles). Full furnishing is an option priced individually.","question":"Is the All-Inclusive package available and how much does it cost?"},{"id":"hk111-faq-2","answer":"The investment is split into eight stages and the next instalment is paid after the previous result has been checked: 10% design and reservation, 20% machine start-up, 10% factory acceptance, 10% packing and shipping, 10% materials on site, 10% shell assembly, 15% shell-and-core stage, 15% handover of keys. After the contract is signed the price of materials is frozen for the whole construction period.","question":"What is the payment schedule and is the price fixed?"},{"id":"hk111-faq-3","answer":"From order to handover of the keys the build takes 4-6 months, with on-site assembly of up to 14 days. The producer provides transport and assembly; the foundation slab is an extra cost outside the All-Inclusive package, and soil replacement is charged at actual cost.","question":"How long does the build take from order to handover of the keys?"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Prefabricated LGS steel frame (galvanised profiles) with mineral wool filling, cement-bonded particleboard, wind barrier and 150 mm facade insulation.', 'Flat roof with an EPDM membrane', 'The design can be adapted with the producer''s architects: changing the partition layout, the size and placement of windows and modifying the building form.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('51a474db-fde6-4dcc-893b-bba72192f355', 'd45da285-893f-5a27-aa33-81c92a9153f2', 'de', 'FrameDEV 5', 'Ein zweigeschossiges Haus in kompakter weißer Form mit Pergola an der Terrasse, mit 192 m² Nutzfläche und Garage. Vier Schlafzimmer und drei Badezimmer. Luft-Wärmepumpe, Fußbodenheizung im ganzen Haus, Lüftung mit Wärmerückgewinnung.', '2026-10-21T17:43:48.657Z'::timestamptz, '2026-10-21T18:12:16.828Z'::timestamptz, '[{"id":"hk111-room-0","name":"Windfang"},{"id":"hk111-room-1","name":"Ankleidezimmer"},{"id":"hk111-room-2","name":"Flur"},{"id":"hk111-room-3","name":"Wohnbereich"},{"id":"hk111-room-4","name":"Vorratsraum"},{"id":"hk111-room-5","name":"Badezimmer"},{"id":"hk111-room-6","name":"Arbeitszimmer"},{"id":"hk111-room-7","name":"Hauswirtschaftsraum"},{"id":"hk111-room-8","name":"Flur mit Treppe"},{"id":"hk111-room-9","name":"Fitnessraum"},{"id":"hk111-room-10","name":"Abstellraum"},{"id":"hk111-room-11","name":"Ankleidezimmer"},{"id":"hk111-room-12","name":"Schlafzimmer"},{"id":"hk111-room-13","name":"Ankleidezimmer"},{"id":"hk111-room-14","name":"Badezimmer"},{"id":"hk111-room-15","name":"Badezimmer"},{"id":"hk111-room-16","name":"Schlafzimmer"},{"id":"hk111-room-17","name":"Schlafzimmer"},{"id":"hk111-room-18","name":"Waschküche"}]'::jsonb, '[{"id":"hk111-faq-1","answer":"Ja, der geschätzte Preis des Pakets All-Inclusive beträgt 1.583.771 PLN. Es umfasst alles aus dem Paket Schlüsselfertig plus Fundamentplatte, Lüftung mit Wärmerückgewinnung, eine Maßküche mit kompletten Geräten und die vollständige Badausstattung (Armaturen, Sanitärkeramik, Fliesen). Die vollständige Möblierung ist eine individuell kalkulierte Option.","question":"Gibt es das Paket All-Inclusive und was kostet es?"},{"id":"hk111-faq-2","answer":"Die Investition ist in acht Etappen aufgeteilt, die nächste Rate wird nach Prüfung des vorherigen Ergebnisses gezahlt: 10 % Entwurf und Reservierung, 20 % Anlauf der Maschinen, 10 % Werksabnahme, 10 % Verpackung und Versand, 10 % Material auf dem Grundstück, 10 % Montage des Rohbaus, 15 % Bauträgerstandard, 15 % Schlüsselübergabe. Nach Vertragsabschluss wird der Materialpreis für die gesamte Bauzeit eingefroren.","question":"Wie sieht der Zahlungsplan aus und ist der Preis fest?"},{"id":"hk111-faq-3","answer":"Von der Bestellung bis zur Schlüsselübergabe dauert die Realisierung 4-6 Monate, die Montage auf dem Grundstück bis zu 14 Tage. Der Hersteller übernimmt Transport und Montage; die Fundamentplatte ist außerhalb des Pakets All-Inclusive ein Zusatzposten, der Bodenaustausch wird nach tatsächlichen Kosten abgerechnet.","question":"Wie lange dauert die Realisierung von der Bestellung bis zur Schlüsselübergabe?"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Vorgefertigtes LGS-Stahlskelett (verzinkte Profile) mit Mineralwolle-Füllung, zementgebundener Spanplatte, Winddichtung und 150 mm Fassadendämmung.', 'Flachdach mit EPDM-Membran', 'Der Entwurf kann mit den Architekten des Herstellers angepasst werden: Änderung der Trennwände, Größe und Anordnung der Fenster sowie Änderung der Gebäudeform.', NULL) ON CONFLICT DO NOTHING;
