INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('1e8ef5ac-4c3a-410c-b8cd-3b2868b40e89', 'a9a54b5f-87c2-507f-a36c-8a586c2b4d3c', 'de', 'FrameDEV 8', 'Ein zweigeschossiges Haus mit Flachdach, großen Verglasungen und Terrassen, mit 223 m² Nutzfläche und Garage für zwei Autos. Im Erdgeschoss ein Wohnbereich, ein Freizeitraum und eine Suite mit Schlafzimmer, Ankleide und Bad, im Obergeschoss drei Schlafzimmer mit Ankleidezimmern. Mechanische Lüftung mit Wärmerückgewinnung.', '2026-10-21T17:43:49.228Z'::timestamptz, '2026-10-21T18:12:20.767Z'::timestamptz, '[]'::jsonb, '[{"id":"fdpl-zx154-faq-1","answer":"Ja, der geschätzte Preis des Pakets All-Inclusive beträgt 1.833.173 PLN. Es umfasst alles aus dem Paket Schlüsselfertig plus Fundamentplatte, Lüftung mit Wärmerückgewinnung, eine Maßküche mit kompletten Geräten und die vollständige Badausstattung (Armaturen, Sanitärkeramik, Fliesen). Die vollständige Möblierung ist eine individuell kalkulierte Option.","question":"Gibt es das Paket All-Inclusive und was kostet es?"},{"id":"fdpl-zx154-faq-2","answer":"Die Investition ist in acht Etappen aufgeteilt, die nächste Rate wird nach Prüfung des vorherigen Ergebnisses gezahlt: 10 % Entwurf und Reservierung, 20 % Anlauf der Maschinen, 10 % Werksabnahme, 10 % Verpackung und Versand, 10 % Material auf dem Grundstück, 10 % Montage des Rohbaus, 15 % Bauträgerstandard, 15 % Schlüsselübergabe. Nach Vertragsabschluss wird der Materialpreis für die gesamte Bauzeit eingefroren.","question":"Wie sieht der Zahlungsplan aus und ist der Preis fest?"},{"id":"fdpl-zx154-faq-3","answer":"Von der Bestellung bis zur Schlüsselübergabe dauert die Realisierung 4-6 Monate, die Montage auf dem Grundstück bis zu 14 Tage. Der Hersteller übernimmt Transport und Montage; die Fundamentplatte ist außerhalb des Pakets All-Inclusive ein Zusatzposten, der Bodenaustausch wird nach tatsächlichen Kosten abgerechnet.","question":"Wie lange dauert die Realisierung von der Bestellung bis zur Schlüsselübergabe?"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Vorgefertigtes LGS-Stahlskelett (verzinkte Profile) mit Mineralwolle-Füllung, zementgebundener Spanplatte, Winddichtung und 150 mm Fassadendämmung.', 'Flachdach, Eindeckung: PVC-Folie oder Bitumenbahn', 'Der Entwurf kann mit den Architekten des Herstellers angepasst werden: Änderung der Trennwände, Größe und Anordnung der Fenster sowie Änderung der Gebäudeform.', NULL) ON CONFLICT DO NOTHING;
