INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('eb9484df-1036-4ab1-a52d-b931e1fc6298', '6d528e4c-ed3b-5560-a7f6-13948c31a67a', 'en', 'FrameDEV 3', 'A single-storey house with 242 m² of usable area, a two-car garage and extensive terraces. Four bedrooms, two bathrooms (one with a sauna), a large pantry and a boiler room with a utility room. Underfloor heating throughout the house, ventilation with heat recovery.', '2026-10-21T17:43:48.266Z'::timestamptz, '2026-10-21T18:12:15.024Z'::timestamptz, '[{"id":"hk88-room-0","name":"Entrance lobby"},{"id":"hk88-room-1","name":"Walk-in wardrobe"},{"id":"hk88-room-2","name":"Hallway"},{"id":"hk88-room-3","name":"Kitchen"},{"id":"hk88-room-4","name":"Pantry"},{"id":"hk88-room-5","name":"Dining room"},{"id":"hk88-room-6","name":"Living room"},{"id":"hk88-room-7","name":"Room"},{"id":"hk88-room-8","name":"Room"},{"id":"hk88-room-9","name":"Room"},{"id":"hk88-room-10","name":"Bedroom"},{"id":"hk88-room-11","name":"Walk-in wardrobe"},{"id":"hk88-room-12","name":"Walk-in wardrobe"},{"id":"hk88-room-13","name":"Bathroom with sauna"},{"id":"hk88-room-14","name":"Laundry room"},{"id":"hk88-room-15","name":"Bathroom"},{"id":"hk88-room-16","name":"Boiler room / utility room"},{"id":"hk88-room-17","name":"Garage"}]'::jsonb, '[{"id":"hk88-faq-1","answer":"Yes, the estimated price of the All-Inclusive package is PLN 2,372,233. It covers everything in the Turnkey package plus the foundation slab, heat recovery ventilation, a made-to-measure kitchen with full appliances and complete bathroom fittings (taps, sanitaryware, tiles). Full furnishing is an option priced individually.","question":"Is the All-Inclusive package available and how much does it cost?"},{"id":"hk88-faq-2","answer":"The investment is split into eight stages and the next instalment is paid after the previous result has been checked: 10% design and reservation, 20% machine start-up, 10% factory acceptance, 10% packing and shipping, 10% materials on site, 10% shell assembly, 15% shell-and-core stage, 15% handover of keys. After the contract is signed the price of materials is frozen for the whole construction period.","question":"What is the payment schedule and is the price fixed?"},{"id":"hk88-faq-3","answer":"From order to handover of the keys the build takes 4-6 months, with on-site assembly of up to 14 days. The producer provides transport and assembly; the foundation slab is an extra cost outside the All-Inclusive package, and soil replacement is charged at actual cost.","question":"How long does the build take from order to handover of the keys?"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Prefabricated LGS steel frame (galvanised profiles) with mineral wool filling, cement-bonded particleboard, wind barrier and 150 mm facade insulation.', 'Flat roof with an EPDM membrane', 'The design can be adapted with the producer''s architects: changing the partition layout, the size and placement of windows and modifying the building form.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('e91197c7-e225-443b-a3c7-04355f31ba35', '6d528e4c-ed3b-5560-a7f6-13948c31a67a', 'de', 'FrameDEV 3', 'Ein eingeschossiges Haus mit 242 m² Nutzfläche, Garage für zwei Autos und großzügigen Terrassen. Vier Schlafzimmer, zwei Badezimmer (eines mit Sauna), eine große Vorratskammer sowie Heizraum mit Hauswirtschaftsraum. Fußbodenheizung im ganzen Haus, Lüftung mit Wärmerückgewinnung.', '2026-10-21T17:43:48.266Z'::timestamptz, '2026-10-21T18:12:15.024Z'::timestamptz, '[{"id":"hk88-room-0","name":"Windfang"},{"id":"hk88-room-1","name":"Ankleidezimmer"},{"id":"hk88-room-2","name":"Flur"},{"id":"hk88-room-3","name":"Küche"},{"id":"hk88-room-4","name":"Vorratsraum"},{"id":"hk88-room-5","name":"Esszimmer"},{"id":"hk88-room-6","name":"Wohnzimmer"},{"id":"hk88-room-7","name":"Zimmer"},{"id":"hk88-room-8","name":"Zimmer"},{"id":"hk88-room-9","name":"Zimmer"},{"id":"hk88-room-10","name":"Schlafzimmer"},{"id":"hk88-room-11","name":"Ankleidezimmer"},{"id":"hk88-room-12","name":"Ankleidezimmer"},{"id":"hk88-room-13","name":"Badezimmer mit Sauna"},{"id":"hk88-room-14","name":"Waschküche"},{"id":"hk88-room-15","name":"Badezimmer"},{"id":"hk88-room-16","name":"Heizraum / Hauswirtschaftsraum"},{"id":"hk88-room-17","name":"Garage"}]'::jsonb, '[{"id":"hk88-faq-1","answer":"Ja, der geschätzte Preis des Pakets All-Inclusive beträgt 2.372.233 PLN. Es umfasst alles aus dem Paket Schlüsselfertig plus Fundamentplatte, Lüftung mit Wärmerückgewinnung, eine Maßküche mit kompletten Geräten und die vollständige Badausstattung (Armaturen, Sanitärkeramik, Fliesen). Die vollständige Möblierung ist eine individuell kalkulierte Option.","question":"Gibt es das Paket All-Inclusive und was kostet es?"},{"id":"hk88-faq-2","answer":"Die Investition ist in acht Etappen aufgeteilt, die nächste Rate wird nach Prüfung des vorherigen Ergebnisses gezahlt: 10 % Entwurf und Reservierung, 20 % Anlauf der Maschinen, 10 % Werksabnahme, 10 % Verpackung und Versand, 10 % Material auf dem Grundstück, 10 % Montage des Rohbaus, 15 % Bauträgerstandard, 15 % Schlüsselübergabe. Nach Vertragsabschluss wird der Materialpreis für die gesamte Bauzeit eingefroren.","question":"Wie sieht der Zahlungsplan aus und ist der Preis fest?"},{"id":"hk88-faq-3","answer":"Von der Bestellung bis zur Schlüsselübergabe dauert die Realisierung 4-6 Monate, die Montage auf dem Grundstück bis zu 14 Tage. Der Hersteller übernimmt Transport und Montage; die Fundamentplatte ist außerhalb des Pakets All-Inclusive ein Zusatzposten, der Bodenaustausch wird nach tatsächlichen Kosten abgerechnet.","question":"Wie lange dauert die Realisierung von der Bestellung bis zur Schlüsselübergabe?"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Vorgefertigtes LGS-Stahlskelett (verzinkte Profile) mit Mineralwolle-Füllung, zementgebundener Spanplatte, Winddichtung und 150 mm Fassadendämmung.', 'Flachdach mit EPDM-Membran', 'Der Entwurf kann mit den Architekten des Herstellers angepasst werden: Änderung der Trennwände, Größe und Anordnung der Fenster sowie Änderung der Gebäudeform.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('d869cddf-637b-49ee-b4ec-dc8b6df8f1f5', '6d528e4c-ed3b-5560-a7f6-13948c31a67a', 'nl', 'FrameDEV 3', 'Een gelijkvloerse woning met 242 m² bruikbare oppervlakte, een garage voor twee auto''s en ruime terrassen. Vier slaapkamers, twee badkamers (waarvan één met sauna), een grote voorraadkast en een ketelruimte met bijkeuken. Vloerverwarming in het hele huis, ventilatie met warmteterugwinning.', '2026-10-21T17:43:48.266Z'::timestamptz, '2026-10-21T18:12:15.024Z'::timestamptz, '[{"id":"hk88-room-0","name":"Portaal"},{"id":"hk88-room-1","name":"Inloopkast"},{"id":"hk88-room-2","name":"Gang"},{"id":"hk88-room-3","name":"Keuken"},{"id":"hk88-room-4","name":"Voorraadkast"},{"id":"hk88-room-5","name":"Eetkamer"},{"id":"hk88-room-6","name":"Woonkamer"},{"id":"hk88-room-7","name":"Kamer"},{"id":"hk88-room-8","name":"Kamer"},{"id":"hk88-room-9","name":"Kamer"},{"id":"hk88-room-10","name":"Slaapkamer"},{"id":"hk88-room-11","name":"Inloopkast"},{"id":"hk88-room-12","name":"Inloopkast"},{"id":"hk88-room-13","name":"Badkamer met sauna"},{"id":"hk88-room-14","name":"Wasruimte"},{"id":"hk88-room-15","name":"Badkamer"},{"id":"hk88-room-16","name":"Ketelruimte / bijkeuken"},{"id":"hk88-room-17","name":"Garage"}]'::jsonb, '[{"id":"hk88-faq-1","answer":"Ja, de geschatte prijs van het pakket All-Inclusive is 2.372.233 PLN. Het omvat alles uit het pakket Sleutelklaar plus de funderingsplaat, ventilatie met warmteterugwinning, een keuken op maat met complete apparatuur en volledige badkamerinrichting (kranen, sanitair, tegels). Volledige meubilering is een optie die individueel wordt geprijsd.","question":"Is het pakket All-Inclusive beschikbaar en wat kost het?"},{"id":"hk88-faq-2","answer":"De investering is verdeeld over acht etappes en de volgende termijn wordt betaald nadat het vorige resultaat is gecontroleerd: 10% ontwerp en reservering, 20% opstarten van de machines, 10% fabrieksoplevering, 10% verpakking en verzending, 10% materiaal op de bouwplaats, 10% montage van de ruwbouw, 15% casco-stadium, 15% overdracht van de sleutels. Na ondertekening van het contract wordt de materiaalprijs voor de hele bouwperiode bevroren.","question":"Hoe ziet het betalingsschema eruit en is de prijs vast?"},{"id":"hk88-faq-3","answer":"Van bestelling tot overdracht van de sleutels duurt de realisatie 4-6 maanden, met een montage op de bouwplaats van maximaal 14 dagen. De producent verzorgt transport en montage; de funderingsplaat is buiten het pakket All-Inclusive een meerprijs en grondvervanging wordt tegen werkelijke kosten gerekend.","question":"Hoe lang duurt de realisatie van bestelling tot overdracht van de sleutels?"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Geprefabriceerd LGS-staalskelet (verzinkte profielen) met minerale wolvulling, cementgebonden spaanplaat, windscherm en 150 mm gevelisolatie.', 'Plat dak met EPDM-membraan', 'Het ontwerp kan samen met de architecten van de producent worden aangepast: een andere indeling van de tussenwanden, andere maat en plaatsing van de ramen en een gewijzigde vorm van het gebouw.', NULL) ON CONFLICT DO NOTHING;
